style.css:
/* ==========================================
   1. GLOBAL HACKER THEME (Black & Green)
   ========================================== */

/* Dark background and matrix-green text for the entire page */
body {
  background-color: #0d0d0d !important;
  color: #00ff41 !important;
  font-family: 'Courier New', Courier, monospace;
  margin: 0;
  padding: 20px;
}

/* Green borders and subtle glow for common HTML elements */
h1, h2, h3, h4, h5, h6 {
  color: #00ff41 !important;
  text-shadow: 0 0 5px #00ff41, 0 0 10px #00ff41;
  border-bottom: 1px solid #00ff41;
  padding-bottom: 5px;
}

p, span, div, li {
  color: #00ff41 !important;
  text-shadow: 0 0 2px rgba(0, 255, 65, 0.5);
}

/* Hacker-style Links */
a {
  color: #00ff41 !important;
  text-decoration: none;
  border-bottom: 1px dashed #00ff41;
}

a:hover {
  background-color: #00ff41 !important;
  color: #000000 !important;
  box-shadow: 0 0 10px #00ff41;
}

/* Hacker-style Buttons and Inputs */
button, input, textarea, select {
  background-color: #000000 !important;
  color: #00ff41 !important;
  border: 1px solid #00ff41 !important;
  font-family: 'Courier New', Courier, monospace;
  padding: 8px 12px;
  outline: none;
  box-shadow: 0 0 5px rgba(0, 255, 65, 0.3);
}

button:hover, input:focus, textarea:focus {
  box-shadow: 0 0 12px #00ff41;
  background-color: #051a05 !important;
}

/* Custom Green Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: #000000;
}
::-webkit-scrollbar-thumb {
  background: #00ff41;
  box-shadow: 0 0 5px #00ff41;
}

/* Text Selection Color */
::selection {
  background: #00ff41;
  color: #000000;
}


/* ==========================================
   2. RAINBOW CURSOR (Using SVG Data URI)
   ========================================== */

/* 
   Keyframe animation that shifts the hue (color) 
   of the custom SVG cursor over time.
*/
@keyframes rainbowCursor {
  0%   { filter: hue-rotate(0deg) drop-shadow(0 0 2px rgba(255, 0, 0, 0.8)); }
  100% { filter: hue-rotate(360deg) drop-shadow(0 0 2px rgba(255, 0, 0, 0.8)); }
}

/* Apply the custom cursor to everything and animate it */
html, body, *, a, button, input {
  /* High-resolution sharp pointer SVG encoded directly in CSS */
  cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path fill="%23ff0000" stroke="%23ffffff" stroke-width="1" d="M3 2v18l5-5 4 8 3-1-4-8 7-1z"/></svg>'), auto !important;
  
  /* Cycles through the rainbow color wheel continuously over 3 seconds */
  animation: rainbowCursor 3s infinite linear;
}
